changeSet.sql:
UPDATE pep_function_parser SET covered_scope = CONVERT(CAST(CONVERT(covered_scope USING latin1) AS BINARY) USING utf8mb4) WHERE (INSTR(HEX(covered_scope), 'C383C2') > 0 OR INSTR(HEX(covered_scope), 'C3A2E282AC') > 0) AND CONVERT(CONVERT(covered_scope USING latin1) USING utf8mb4) = covered_scope AND (LENGTH(CONVERT(CAST(CONVERT(covered_scope USING latin1) AS BINARY) USING utf8mb4)) - LENGTH(REPLACE(CONVERT(CAST(CONVERT(covered_scope USING latin1) AS BINARY) USING utf8mb4), '?', ''))) = (LENGTH(covered_scope) - LENGTH(REPLACE(covered_scope, '?', '')));
UPDATE parser SET description = CONVERT(CAST(CONVERT(description USING latin1) AS BINARY) USING utf8mb4) WHERE (INSTR(HEX(description), 'C383C2') > 0 OR INSTR(HEX(description), 'C3A2E282AC') > 0) AND CONVERT(CONVERT(description USING latin1) USING utf8mb4) = description AND (LENGTH(CONVERT(CAST(CONVERT(description USING latin1) AS BINARY) USING utf8mb4)) - LENGTH(REPLACE(CONVERT(CAST(CONVERT(description USING latin1) AS BINARY) USING utf8mb4), '?', ''))) = (LENGTH(description) - LENGTH(REPLACE(description, '?', '')));
UPDATE parser SET name = CONVERT(CAST(CONVERT(name USING latin1) AS BINARY) USING utf8mb4) WHERE (INSTR(HEX(name), 'C383C2') > 0 OR INSTR(HEX(name), 'C3A2E282AC') > 0) AND CONVERT(CONVERT(name USING latin1) USING utf8mb4) = name AND (LENGTH(CONVERT(CAST(CONVERT(name USING latin1) AS BINARY) USING utf8mb4)) - LENGTH(REPLACE(CONVERT(CAST(CONVERT(name USING latin1) AS BINARY) USING utf8mb4), '?', ''))) = (LENGTH(name) - LENGTH(REPLACE(name, '?', '')));
